def main(glyph_name):
    from fontTools.ttLib import TTFont
    from fontTools.pens.recordingPen import RecordingPen
    import numpy as np
    from scipy.ndimage import distance_transform_edt
    from skimage.morphology import skeletonize, thin
    import cv2

    def bezier_sample(p0, p1, p2, p3, num_points=20):
        """ 使用德卡斯特里奥算法对三阶贝塞尔曲线采样 """
        t = np.linspace(0, 1, num_points)
        points = []
        for ti in t:
            x = (1 - ti) ** 3 * p0[0] + 3 * (1 - ti) ** 2 * ti * p1[0] + 3 * (1 - ti) * ti ** 2 * p2[0] + ti ** 3 * p3[0]
            y = (1 - ti) ** 3 * p0[1] + 3 * (1 - ti) ** 2 * ti * p1[1] + 3 * (1 - ti) * ti ** 2 * p2[1] + ti ** 3 * p3[1]
            points.append((x, y))
        return points
    
    def quadratic_sample(p0, p1, p2, num_points=15):
        """ 对二阶贝塞尔曲线采样 """
        t = np.linspace(0, 1, num_points)
        points = []
        for ti in t:
            x = (1 - ti) ** 2 * p0[0] + 2 * (1 - ti) * ti * p1[0] + ti ** 2 * p2[0]
            y = (1 - ti) ** 2 * p0[1] + 2 * (1 - ti) * ti * p1[1] + ti ** 2 * p2[1]
            points.append((x, y))
        return points

    # 尝试加载多种常见字体，如果一个不存在则尝试下一个
    font_paths = ['arial.ttf', 'Arial.ttf', 'times.ttf', 'Times New Roman.ttf', 'simhei.ttf', 'simsun.ttc']
    font = None
    
    for font_path in font_paths:
        try:
            font = TTFont(font_path)
            print(f"成功加载字体: {font_path}")
            break
        except Exception as e:
            print(f"无法加载字体 {font_path}: {e}")
    
    if font is None:
        raise Exception("无法加载任何字体文件，请确保至少有一个可用字体")
    
    # 获取字体中的所有字形名称
    glyph_names = font.getGlyphOrder()
    print(f"字体包含 {len(glyph_names)} 个字形")
    
    # 选择一个更复杂的字形，如果'S'不存在则使用第一个非空字形
    if glyph_name not in font.getGlyphSet():
        for name in glyph_names:
            if name != '.notdef':
                glyph_name = name
                break
    
    print(f"使用字形: {glyph_name}")
    glyph = font.getGlyphSet()[glyph_name]
    pen = RecordingPen()
    glyph.draw(pen)
    
    # 创建一个高分辨率的二值图像来表示字形
    canvas_size = 500
    img = np.zeros((canvas_size, canvas_size), dtype=np.uint8)
    
    # 获取字形的边界框
    all_points = []
    for cmd in pen.value:
        cmd_type = cmd[0]
        if cmd_type == 'moveTo' or cmd_type == 'lineTo':
            all_points.append(cmd[1][0])
        elif cmd_type == 'qCurveTo':
            points = cmd[1]
            if points[-1] is not None:  # 跳过None结尾的命令
                all_points.extend([p for p in points if p is not None])
        elif cmd_type == 'curveTo':
            all_points.extend(cmd[1])
    
    if not all_points:
        raise Exception("无法从字形中提取点")
    
    # 计算边界框
    x_coords = [p[0] for p in all_points]
    y_coords = [p[1] for p in all_points]
    xMin, yMin = min(x_coords), min(y_coords)
    xMax, yMax = max(x_coords), max(y_coords)
    
    print(f"字形边界框: ({xMin}, {yMin}) - ({xMax}, {yMax})")
    
    # 计算缩放比例
    width = xMax - xMin
    height = yMax - yMin
    target_size = 400  # 留出边距
    scale = min(target_size / width, target_size / height) if width > 0 and height > 0 else 1.0
    
    # 计算偏移量，使字形居中
    x_offset = (canvas_size - width * scale) / 2
    y_offset = (canvas_size - height * scale) / 2
    
    # 绘制字形轮廓到图像上
    def draw_glyph_to_image(img, pen_commands, scale, x_offset, y_offset):
        import numpy as np
        
        # 创建多边形点列表
        polygons = []
        current_polygon = []
        current_point = None
        
        for cmd in pen_commands:
            cmd_type = cmd[0]
            
            if cmd_type == 'moveTo':
                if current_polygon:
                    polygons.append(np.array(current_polygon, dtype=np.int32))
                    current_polygon = []
                
                x, y = cmd[1][0]
                x = int((x - xMin) * scale + x_offset)
                y = int(canvas_size - ((y - yMin) * scale + y_offset))
                current_point = (x, y)
                current_polygon.append(current_point)
                
            elif cmd_type == 'lineTo':
                x, y = cmd[1][0]
                x = int((x - xMin) * scale + x_offset)
                y = int(canvas_size - ((y - yMin) * scale + y_offset))
                current_polygon.append((x, y))
                current_point = (x, y)
                
            elif cmd_type == 'qCurveTo':
                points = cmd[1]
                if points[-1] is None:
                    continue
                
                # 对二阶贝塞尔曲线采样
                p0 = current_point
                for i in range(0, len(points)-1):
                    p1 = points[i]
                    p2 = points[i+1]
                    
                    # 转换控制点坐标
                    p1_x = int((p1[0] - xMin) * scale + x_offset)
                    p1_y = int(canvas_size - ((p1[1] - yMin) * scale + y_offset))
                    p2_x = int((p2[0] - xMin) * scale + x_offset)
                    p2_y = int(canvas_size - ((p2[1] - yMin) * scale + y_offset))
                    
                    # 采样曲线上的点
                    for t in np.linspace(0, 1, 20):
                        x = (1-t)**2 * p0[0] + 2*(1-t)*t * p1_x + t**2 * p2_x
                        y = (1-t)**2 * p0[1] + 2*(1-t)*t * p1_y + t**2 * p2_y
                        current_polygon.append((int(x), int(y)))
                    
                    p0 = (p2_x, p2_y)
                
                current_point = p0
                
            elif cmd_type == 'curveTo':
                # 三阶贝塞尔曲线
                p1, p2, p3 = cmd[1]
                
                # 转换控制点坐标
                p1_x = int((p1[0] - xMin) * scale + x_offset)
                p1_y = int(canvas_size - ((p1[1] - yMin) * scale + y_offset))
                p2_x = int((p2[0] - xMin) * scale + x_offset)
                p2_y = int(canvas_size - ((p2[1] - yMin) * scale + y_offset))
                p3_x = int((p3[0] - xMin) * scale + x_offset)
                p3_y = int(canvas_size - ((p3[1] - yMin) * scale + y_offset))
                
                # 采样曲线上的点
                for t in np.linspace(0, 1, 20):
                    x = (1-t)**3 * current_point[0] + 3*(1-t)**2*t * p1_x + 3*(1-t)*t**2 * p2_x + t**3 * p3_x
                    y = (1-t)**3 * current_point[1] + 3*(1-t)**2*t * p1_y + 3*(1-t)*t**2 * p2_y + t**3 * p3_y
                    current_polygon.append((int(x), int(y)))
                
                current_point = (p3_x, p3_y)
                
            elif cmd_type == 'closePath':
                if current_polygon and len(current_polygon) > 2:
                    # 闭合多边形
                    if current_polygon[0] != current_polygon[-1]:
                        current_polygon.append(current_polygon[0])
                    polygons.append(np.array(current_polygon, dtype=np.int32))
                    current_polygon = []
        
        # 添加最后一个多边形
        if current_polygon and len(current_polygon) > 2:
            polygons.append(np.array(current_polygon, dtype=np.int32))
        
        # 绘制所有多边形
        for polygon in polygons:
            cv2.fillPoly(img, [polygon], 255)
        
        return img
    
    # 绘制字形到图像
    img = draw_glyph_to_image(img, pen.value, scale, x_offset, y_offset)
    
    # 计算距离变换，用于改进骨架提取
    dist_transform = distance_transform_edt(img > 0)
    
    # 使用细化算法提取骨架
    skeleton = thin(img > 0)
    
    # 将骨架转换为点列表
    skeleton_points = []
    y_indices, x_indices = np.where(skeleton > 0)
    
    # 对骨架点进行排序，使其形成连续的线
    if len(x_indices) > 0:
        # 首先找到端点（只有一个邻居的点）
        endpoints = []
        for i in range(len(x_indices)):
            x, y = x_indices[i], y_indices[i]
            # 检查8个邻域
            neighbors = 0
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < canvas_size and 0 <= ny < canvas_size and skeleton[ny, nx]:
                        neighbors += 1
            if neighbors <= 1:  # 端点
                endpoints.append((x, y))
        
        # 如果找到端点，从最上方的端点开始
        if endpoints:
            start_point = min(endpoints, key=lambda p: p[1])
        else:
            # 如果没有端点（可能是闭合曲线），选择最上方的点
            start_idx = np.argmin(y_indices)
            start_point = (x_indices[start_idx], y_indices[start_idx])
        
        # 使用改进的路径跟踪算法
        ordered_points = [start_point]
        visited = set([start_point])
        current = start_point
        
        while len(visited) < len(x_indices):
            # 查找当前点的未访问邻居
            neighbors = []
            x, y = current
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    if dx == 0 and dy == 0:
                        continue
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < canvas_size and 0 <= ny < canvas_size and skeleton[ny, nx]:
                        neighbor = (nx, ny)
                        if neighbor not in visited:
                            neighbors.append(neighbor)
            
            if neighbors:
                # 选择最近的邻居
                next_point = min(neighbors, key=lambda p: (p[0]-x)**2 + (p[1]-y)**2)
                ordered_points.append(next_point)
                visited.add(next_point)
                current = next_point
            else:
                # 如果没有未访问的邻居，找一个新的起点
                unvisited = [(x_indices[i], y_indices[i]) for i in range(len(x_indices)) if (x_indices[i], y_indices[i]) not in visited]
                if not unvisited:
                    break
                
                # 找到离当前路径最近的未访问点
                if ordered_points:
                    # 过滤掉None值，只使用有效的点计算距离
                    valid_points = [q for q in ordered_points[-5:] if q is not None]
                    if valid_points:
                        next_point = min(unvisited, key=lambda p: min((p[0]-q[0])**2 + (p[1]-q[1])**2 for q in valid_points))
                    else:
                        next_point = unvisited[0]
                else:
                    next_point = unvisited[0]
                
                # 添加一个None作为断点标记
                ordered_points.append(None)
                ordered_points.append(next_point)
                visited.add(next_point)
                current = next_point
        
        # 移除None并分割成多个路径
        paths = []
        current_path = []
        for p in ordered_points:
            if p is None:
                if current_path:
                    paths.append(current_path)
                    current_path = []
            else:
                current_path.append(p)
        
        if current_path:
            paths.append(current_path)
        
        # 如果有多个路径，不仅保留最长的一个，还要保留其他重要路径
        if paths:
            # 按长度排序路径
            sorted_paths = sorted(paths, key=len, reverse=True)
            
            # 保留最长的路径和其他长度超过阈值的路径
            min_path_length = max(10, len(sorted_paths[0]) * 0.3)  # 至少10个点或最长路径的30%
            
            important_paths = [path for path in sorted_paths if len(path) >= min_path_length]
            
            # 合并所有重要路径
            skeleton_points = []
            for path in important_paths:
                if skeleton_points:
                    skeleton_points.append(None)  # 添加路径分隔符
                skeleton_points.extend(path)
        else:
            skeleton_points = []
    
    print(f"提取到 {len(skeleton_points)} 个中心线点")
    
    # 平滑处理中心线 - 对每个子路径单独平滑
    if skeleton_points:
        # 将点列表分割成多个子路径
        sub_paths = []
        current_path = []
        
        for point in skeleton_points:
            if point is None:
                if current_path:
                    sub_paths.append(current_path)
                    current_path = []
            else:
                current_path.append(point)
        
        if current_path:
            sub_paths.append(current_path)
        
        # 对每个子路径单独平滑
        smoothed_paths = []
        for path in sub_paths:
            if len(path) > 5:
                # 使用移动平均平滑
                window_size = 5
                smoothed_path = []
                
                for i in range(len(path)):
                    # 获取窗口内的点
                    window_start = max(0, i - window_size // 2)
                    window_end = min(len(path), i + window_size // 2 + 1)
                    window = path[window_start:window_end]
                    
                    # 计算平均位置
                    avg_x = sum(p[0] for p in window) / len(window)
                    avg_y = sum(p[1] for p in window) / len(window)
                    
                    smoothed_path.append((avg_x, avg_y))
                
                smoothed_paths.append(smoothed_path)
            else:
                smoothed_paths.append(path)
        
        # 重新组合所有平滑后的子路径
        skeleton_points = []
        for i, path in enumerate(smoothed_paths):
            skeleton_points.extend(path)
            if i < len(smoothed_paths) - 1:
                skeleton_points.append(None)
        
        # 移除None分隔符，生成最终的点列表
        final_points = []
        for point in skeleton_points:
            if point is not None:
                final_points.append(point)
        
        skeleton_points = final_points
    
    # 修剪端点，对前后端点采用不同的修剪比例
    if len(skeleton_points) > 10:
        # 前端移除更多的点以去除左上角的小尾巴
        front_trim_count = max(3, int(len(skeleton_points) * 0.03))  # 增加前端修剪比例
        back_trim_count = max(1, int(len(skeleton_points) * 0.015))
        skeleton_points = skeleton_points[front_trim_count:-back_trim_count]
    
    # 额外检查并移除左上角的异常点
    if len(skeleton_points) > 10:
        # 计算前几个点的平均方向
        directions = []
        for i in range(1, min(10, len(skeleton_points))):
            dx = skeleton_points[i][0] - skeleton_points[i-1][0]
            dy = skeleton_points[i][1] - skeleton_points[i-1][1]
            if dx != 0 or dy != 0:  # 避免除以零
                angle = np.arctan2(dy, dx)
                directions.append(angle)
        
        # 如果前几个点的方向变化很大，可能是小尾巴，多移除几个点
        if directions and len(directions) > 3:
            angle_diffs = [abs(directions[i] - directions[i-1]) for i in range(1, len(directions))]
            if max(angle_diffs) > np.pi/2:  # 如果有大于90度的转弯
                extra_trim = max(2, int(len(skeleton_points) * 0.02))
                skeleton_points = skeleton_points[extra_trim:]
    
    # 减少点的数量（采样），控制在200个点以内
    if len(skeleton_points) > 200:
        # 计算采样步长，确保最终点数不超过200
        step = max(1, len(skeleton_points) // 200)
        sampled_points = []
        
        # 使用步长采样，但保留关键点（如拐角点）
        i = 0
        while i < len(skeleton_points):
            current_point = skeleton_points[i]
            sampled_points.append(current_point)
            
            # 如果还有足够的点来检查拐角
            if i > 0 and i < len(skeleton_points) - 1:
                # 计算当前点与前后点形成的角度
                prev_point = skeleton_points[i-1]
                next_point = skeleton_points[i+1]
                
                if prev_point is not None and next_point is not None:
                    # 计算向量
                    v1 = (current_point[0] - prev_point[0], current_point[1] - prev_point[1])
                    v2 = (next_point[0] - current_point[0], next_point[1] - current_point[1])
                    
                    # 计算向量长度
                    len_v1 = np.sqrt(v1[0]**2 + v1[1]**2)
                    len_v2 = np.sqrt(v2[0]**2 + v2[1]**2)
                    
                    # 避免除以零
                    if len_v1 > 0 and len_v2 > 0:
                        # 计算点积
                        dot_product = v1[0]*v2[0] + v1[1]*v2[1]
                        cos_angle = dot_product / (len_v1 * len_v2)
                        # 限制cos值在[-1, 1]范围内
                        cos_angle = max(-1, min(1, cos_angle))
                        angle = np.arccos(cos_angle)
                        
                        # 如果角度大于30度，认为是拐角点，减小步长以保留更多细节
                        if angle > np.pi/6:
                            i += max(1, step // 2)
                            continue
            
            i += step
        
        # 确保包含最后一个点
        if skeleton_points and sampled_points and sampled_points[-1] != skeleton_points[-1]:
            sampled_points.append(skeleton_points[-1])
        
        skeleton_points = sampled_points
    
    print(f"最终中心线点数: {len(skeleton_points)}")
    
    # 可视化结果
    try:
        import matplotlib.pyplot as plt
        plt.figure(figsize=(8, 8))
        
        # 绘制原始字形
        plt.imshow(img, cmap='gray', alpha=0.3)
        
        # 绘制中心线
        x_coords = [p[0] for p in skeleton_points]
        y_coords = [p[1] for p in skeleton_points]
        plt.plot(x_coords, y_coords, 'r-', linewidth=2)
        plt.scatter(x_coords, y_coords, c='blue', s=10)
        
        plt.axis('equal')
        plt.xlim(0, canvas_size)
        plt.ylim(canvas_size, 0)  # 反转Y轴以匹配图像坐标
        plt.title(f'字形 "{glyph_name}" 中心线')
        plt.savefig(f'glyph_{glyph_name}_centerline.png')
        print(f"已保存中心线图像到 glyph_{glyph_name}_centerline.png")
    except ImportError:
        print("未安装matplotlib，跳过可视化")
    
    # 输出前10个点示例
    print("中心线点示例 (前10个):")
    for i, point in enumerate(skeleton_points[:10]):
        print(f"点 {i+1}: {point}")
    
    return skeleton_points

